hor+" keywords="+string.Join(",",material.shaderKeywords));foreach(var v in WaterVolume.Instances)if(v.m_heightmap&&v.m_waterSurface){Logger.LogInfo("NATIVE reflection="+v.m_waterSurface.reflectionProbeUsage+" anchor="+v.m_waterSurface.probeAnchor+" keywords="+string.Join(",",v.m_waterSurface.sharedMaterial.shaderKeywords));break;}var re=ReflectionUpdate.instance;Logger.LogInfo("REFRESH interval="+re.m_interval+" blendDuration="+re.m_transitionDuration+" distances="+re.m_probe1.blendDistance+","+re.m_probe2.blendDistance);Logger.LogInfo("PROBE shader="+material.shader.name+" mesh="+mesh.GetInstanceID()+" materials="+material.GetInstanceID());
