while(Time.time-start<10){yield return null;float now=material.GetFloat("_WaterTime");csv.AppendLine((Time.time-start)+","+now+","+(now-old)+","+r.GetComponent<MeshFilter>().sharedMesh.GetInstanceID()+","+r.sharedMaterial.GetInstanceID()+","+(rebuilds-initial));old=now;r.GetClosestReflectionProbes(probes);if(Time.time>=next){next=Time.time+.2f;Logger.LogInfo("REFLECTION "+(Time.time-start)+" "+string.Join(";",probes.Select(q=>q.probe.GetInstanceID()+":"+q.weight)));camera.targetTexture=rt;camera.Render();var saved=RenderTexture.active;RenderTexture.active=rt;tex.ReadPixels(new Rect(0,0,640,480),0,0);tex.Apply();File.WriteAllBytes(root+"/pond-"+(shot++).ToString("000")+".png",tex.EncodeToPNG());RenderTexture.active=saved;camera.targetTexture=null;}}
camera.targetTexture=rt;camera.Render();var active=RenderTexture.active;RenderTexture.active=rt;tex.ReadPixels(new Rect(0,0,640,480),0,0);tex.Apply();File.WriteAllBytes(root+"/reflection-before.png",tex.EncodeToPNG());r.reflectionProbeUsage=UnityEngine.Rendering.ReflectionProbeUsage.Off;camera.Render();tex.ReadPixels(new Rect(0,0,640,480),0,0);tex.Apply();File.WriteAllBytes(root+"/reflection-after.png",tex.EncodeToPNG());RenderTexture.active=active;camera.targetTexture=null;File.WriteAllText(root+"/surface.csv",csv.ToString());Logger.LogInfo("PROBE COMPLETE rebuilds="+(rebuilds-initial));Application.Quit();}
